<PageTitle>Settings</PageTitle>

<div class="container-fluid">
    <div class="row">
        <!-- Sidebar -->
        <div class="col-md-3 col-lg-2 border-end min-vh-100 p-0">
            <SettingsSidebar ActiveSection="@_activeSection" OnSectionSelected="SetSection" />
        </div>

        <!-- Main Content -->
        <div class="col-md-9 col-lg-10 p-4">
            @if (_loading)
            {
                <div class="d-flex justify-content-center py-5">
                    <div class="spinner-border" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
            else
            {
                @switch (_activeSection)
                {
                    case "Profile":
                        <ProfileSection Profile="@_profile" OnSave="SaveProfileAsync" />
                        break;
                    case "Notifications":
                        <NotificationsSection Prefs="@_notificationPrefs" OnSave="SaveNotificationsAsync" />
                        break;
                    case "Security":
                        <SecuritySection Security="@_security"
                                         OnChangePassword="ChangePasswordAsync"
                                         OnRevokeSession="RevokeSessionAsync" />
                        break;
                    case "Appearance":
                        <AppearanceSection Settings="@_appearance" OnSave="SaveAppearanceAsync" />
                        break;
                }
            }
        </div>
