@namespace sv_be253afe0aef4ae3a929fa9e0a8d5ae1.Components.Pages.Settings
@using sv_be253afe0aef4ae3a929fa9e0a8d5ae1.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="container-fluid">
    <div class="row">
        <!-- Sidebar -->
        <div class="col-md-3 col-lg-2 border-end min-vh-100 p-0">
            <SettingsSidebar ActiveSection="@_activeSection" OnSectionSelected="SetSection" />
        </div>

        <!-- Main Content -->
        <div class="col-md-9 col-lg-10 p-4">
            @if (_loading)
            {
                <div class="d-flex justify-content-center py-5">
                    <div class="spinner-border" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
            else
            {
                @switch (_activeSection)
                {
                    case "Profile":
                        <ProfileSection Profile="@_profile" OnSave="SaveProfileAsync" />
                        break;
                    case "Notifications":
                        <NotificationsSection Prefs="@_notificationPrefs" OnSave="SaveNotificationsAsync" />
                        break;
                    case "Security":
                        <SecuritySection Security="@_security"
                                         OnChangePassword="ChangePasswordAsync"
                                         OnRevokeSession="RevokeSessionAsync" />
                        break;
                    case "Appearance":
                        <AppearanceSection Settings="@_appearance" OnSave="SaveAppearanceAsync" />
                        break;
                }
            }
        </div>
    </div>
</div>

@code {
    private string _activeSection = "Profile";
    private bool _loading = true;

    private UserProfile? _profile;
    private NotificationPrefs? _notificationPrefs;
    private SecuritySettings? _security;
    private AppearanceSettings? _appearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionDataAsync();
    }

    private async Task SetSection(string section)
    {
        _activeSection = section;
        _loading = true;
        await LoadSectionDataAsync();
    }

    private async Task LoadSectionDataAsync()
    {
        switch (_activeSection)
        {
            case "Profile":
                _profile = await SettingsService.GetProfileAsync();
                break;
            case "Notifications":
                _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                break;
            case "Security":
                _security = await SettingsService.GetSecuritySettingsAsync();
                break;
            case "Appearance":
                _appearance = await SettingsService.GetAppearanceAsync();
                break;
        }
        _loading = false;
    }

    private async Task SaveProfileAsync(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        _profile = profile;
    }

    private async Task SaveNotificationsAsync(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
    }

    private async Task ChangePasswordAsync(string newPassword)
    {
        await SettingsService.ChangePasswordAsync("", newPassword);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        _appearance = settings;
    }
}
